679	// Status 返回账户状态：各月累计用量、各账单余额以及当前是否因欠费停用。
680	func (s *Service) Status(accountID string) (AccountStatus, error) {
681		if accountID == "" {
682			return AccountStatus{}, invalidf("account id is empty")
683		}
684		s.mu.Lock()
685		defer s.mu.Unlock()
686		acc, ok := s.accounts[accountID]
687		if !ok {
688			return AccountStatus{}, ErrAccountNotFound
689		}
690	
691		now := s.nowUTC()
692		// 查询即让已到期安排/取消生效：月初零点或终止时刻之后无需上报用量或出账，
693		// 当前条件与订阅状态立即更新。
694		s.settleLocked(acc, now)
695	
696		periodSet := make(map[Month]struct{}, len(acc.usage)+len(acc.bills))
697		for m := range acc.usage {
698			periodSet[m] = struct{}{}
699		}
700		for m := range acc.bills {
701			periodSet[m] = struct{}{}
702		}
703		periods := make([]Month, 0, len(periodSet))
704		for m := range periodSet {
705			periods = append(periods, m)
706		}
707		sortMonths(periods)
708	
709		st := AccountStatus{
710			AccountID:    accountID,
711			Subscribed:   acc.sub != nil,
712			Suspended:    s.isSuspendedLocked(acc, now),
713			MonthlyUsage: make([]Usage, 0, len(periods)),
714			Bills:        make([]BillSummary, 0, len(acc.bills)),
715		}
716		if acc.sub != nil {
717			st.CurrentTerms = acc.sub.terms
718			if acc.sub.pending != nil {
719				pending := *acc.sub.pending
720				st.PendingChange = &pending
721			}
722			if acc.sub.cancelEnd != nil {
723				end := *acc.sub.cancelEnd
724				st.ScheduledEnd = &end
725			}
726		}
727		for _, m := range periods {
728			st.MonthlyUsage = append(st.MonthlyUsage, Usage{Period: m, Total: acc.usage[m]})
729		}
730		for _, m := range periods {
731			if rec, ok := acc.bills[m]; ok {
732				b := rec.bill
733				st.Bills = append(st.Bills, BillSummary{
734					Period:   m,
735					TotalDue: b.TotalDue,
736					Paid:     b.Paid,
737					Balance:  b.Balance,
738					Settled:  b.Settled,
739					DueAt:    b.DueAt,
740				})
741			}
742		}
743		return st, nil
744	}
745	
746	// isSuspendedLocked 报告账户当前是否停用：
747	// 存在到达付款截止时刻仍有余额的账单。调用时持有 s.mu。
748	func (s *Service) isSuspendedLocked(acc *account, now time.Time) bool {
749		for _, rec := range acc.bills {
750			if !rec.bill.Settled && !now.Before(rec.bill.DueAt) {
751				return true
752			}
753		}
754		return false
755	}
756	
757	func sortMonths(ms []Month) {
758		sort.Slice(ms, func(i, j int) bool { return ms[i].Before(ms[j]) })
759	}
760	
761	// addNonNeg 返回两个非负 int64 之和；溢出时 ok=false。
762	func addNonNeg(a, b int64) (int64, bool) {
763		if a > maxInt64-b {
764			return 0, false
765		}
766		return a + b, true
767	}
768	
769	// mulNonNeg 返回两个非负 int64 之积；溢出时 ok=false。
770	func mulNonNeg(a, b int64) (int64, bool) {
771		if a == 0 || b == 0 {
772			return 0, true
773		}
774		if a > maxInt64/b {
775			return 0, false
776		}
777		return a * b, true
778	}
779	
780	// buildBill 依据套餐快照和账期总用量计算账单，所有金额运算做溢出检查。
781	func buildBill(accountID string, period Month, t PlanTerms, totalUsage int64) (Bill, error) {
782		overageUnits := int64(0)
783		if totalUsage > t.IncludedUnits {
784			overageUnits = totalUsage - t.IncludedUnits
785		}
786		overageFee, ok := mulNonNeg(overageUnits, t.OveragePrice)
787		if !ok {
788			return Bill{}, ErrOverflow
789		}
790		subtotal, ok := addNonNeg(t.MonthlyFee, overageFee)
791		if !ok {
792			return Bill{}, ErrOverflow
793		}
794		tax, ok := rateAmount(subtotal, t.TaxRateBasisPoints)
795		if !ok {
796			return Bill{}, ErrOverflow
797		}
798		totalDue, ok := addNonNeg(subtotal, tax)
799		if !ok {
800			return Bill{}, ErrOverflow
801		}
802		b := Bill{
803			AccountID:     accountID,
804			Period:        period,
805			Terms:         t,
806			TotalUsage:    totalUsage,
807			IncludedUnits: t.IncludedUnits,
808			OverageUnits:  overageUnits,
809			MonthlyFee:    t.MonthlyFee,
810			OverageFee:    overageFee,
811			Tax:           tax,
812			TotalDue:      totalDue,
813			Paid:          0,
814			Balance:       totalDue,
815			Settled:       totalDue == 0,
816			DueAt:         period.End().AddDate(0, 0, 7),
817		}
818		return b, nil
819	}
820	
821	// rateAmount 计算 amount*rate/10000 并四舍五入到分（非负数，半数向上）。
822	// 拆分商和余数计算以避免乘积溢出 int64。
823	func rateAmount(amount, rate int64) (int64, bool) {
824		const den = 10000
825		q, r := amount/den, amount%den
826		qr, ok := mulNonNeg(q, rate)
827		if !ok {
828			return 0, false
829		}
830		rr, ok := mulNonNeg(r, rate)
831		if !ok {
832			return 0, false
833		}
834		// 四舍五入：(rr + den/2) / den，rr < den*10001 < 1e8，加 den/2 不溢出。
835		add, ok := addNonNeg(qr, (rr+den/2)/den)
836		if !ok {
837			return 0, false
838		}
839		return add, true
840	}
841

