196		// 只要 1 月尚未出账就接收。
197		clk.t = utc(2026, 2, 1, 0, 0)
198		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "jlate", At: utc(2026, 1, 25, 0, 0), Quantity: 5}); err != nil {
199			t.Fatalf("backfill jan after switch: %v", err)
200		}
201		if u, _ := s.MonthlyUsage("u", jan(2026)); u.Total != 20 {
202			t.Fatalf("jan usage = %d, want 20", u.Total)
203		}
204		janBill, err := s.CreateBill("u", jan(2026))
205		if err != nil {
206			t.Fatal(err)
207		}
208		// 旧套餐 a：用量 20 -> 超额 10 * 100 = 1000，月费 1000，合计 2000。
209		if janBill.Terms.PlanID != "a" || janBill.MonthlyFee != 1000 || janBill.OverageUnits != 10 || janBill.OverageFee != 1000 || janBill.TotalDue != 2000 {
210			t.Fatalf("jan bill mixed terms: %+v", janBill)
211		}
212	
213		// 2 月用量按新套餐：25 单位 -> 超额 5 * 200 = 1000，月费 2000。
214		// 截止前付清 1 月账单，避免欠费停用。
215		if _, err := s.RecordPayment("u", "p", jan(2026), janBill.TotalDue); err != nil {
216			t.Fatal(err)
217		}
218		clk.t = utc(2026, 2, 12, 0, 0)
219		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "f", At: utc(2026, 2, 10, 0, 0), Quantity: 25}); err != nil {
220			t.Fatal(err)
221		}
222		clk.t = utc(2026, 3, 1, 0, 0)
223		febBill, err := s.CreateBill("u", feb(2026))
224		if err != nil {
225			t.Fatal(err)
226		}
227		if febBill.Terms.PlanID != "b" || febBill.MonthlyFee != 2000 || febBill.OverageUnits != 5 || febBill.OverageFee != 1000 || febBill.TotalDue != 3000 {
228			t.Fatalf("feb bill mixed terms: %+v", febBill)
229		}
230		// 1 月账单不受 2 月出账影响。
231		gotJan, _ := s.GetBill("u", jan(2026))
232		if gotJan.TotalUsage != 20 || gotJan.TotalDue != 2000 {
233			t.Fatalf("jan bill changed: %+v", gotJan)
234		}
235	
236		// 已出账月份继续拒绝新事件。
237		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "jnew", At: utc(2026, 1, 26, 0, 0), Quantity: 1}); !errors.Is(err, ErrMonthBilled) {
238			t.Fatalf("new event on billed jan: %v", err)
239		}
240	}
